-- US MD/MBBS (4th Year) clinical case blocks - Geriatrics: Cardiovascular in elderly — isolated systolic HTN, orthostatic hypotension, HFpEF - Part 1 (1-100)
BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'geri-cardiovascular' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic geri-cardiovascular not found.';
    END IF;

    DELETE FROM mcqs WHERE topic_id = v_topic_id;

END $$;
COMMIT;
